#!/usr/bin/env python3
"""A small, dependency-free persistent HTTP key-value service."""

import argparse
import json
import math
import os
import signal
import sys
import tempfile
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit


MAX_BODY = 1024 * 1024


class RequestError(Exception):
    def __init__(self, status, message):
        self.status = status
        self.message = message


def valid_json_value(value):
    """Reject values json.loads accepts but JSON cannot faithfully represent."""
    if isinstance(value, float):
        return math.isfinite(value)
    if isinstance(value, list):
        return all(valid_json_value(item) for item in value)
    if isinstance(value, dict):
        return all(isinstance(key, str) and valid_json_value(item)
                   for key, item in value.items())
    return True


def decode_key(raw):
    if not raw:
        raise RequestError(400, "key must not be empty")
    # urllib's unquote tolerates broken percent escapes, so validate first.
    index = 0
    while index < len(raw):
        if raw[index] == "%":
            if index + 2 >= len(raw) or any(c not in "0123456789abcdefABCDEF"
                                           for c in raw[index + 1:index + 3]):
                raise RequestError(400, "invalid percent-encoding in key")
            index += 3
        else:
            index += 1
    try:
        from urllib.parse import unquote_to_bytes
        key = unquote_to_bytes(raw).decode("utf-8")
    except UnicodeDecodeError:
        raise RequestError(400, "key must be UTF-8")
    if not key or "/" in key:
        raise RequestError(400, "key must be non-empty and must not contain '/'")
    return key


class Store:
    def __init__(self, path):
        self.path = os.path.abspath(path)
        self.lock = threading.RLock()
        self.entries = {}
        self._load()

    def _live_data(self):
        return {key: {"value": entry["value"], "expires_at": entry["expires_at"]}
                for key, entry in self.entries.items()}

    def _write_locked(self):
        directory = os.path.dirname(self.path) or "."
        os.makedirs(directory, exist_ok=True)
        fd, temporary = tempfile.mkstemp(prefix=".kv-", suffix=".tmp", dir=directory)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as file:
                json.dump({"entries": self._live_data()}, file,
                          ensure_ascii=False, separators=(",", ":"), allow_nan=False)
                file.flush()
                os.fsync(file.fileno())
            os.replace(temporary, self.path)
            # Make the rename durable where the platform supports directory fsync.
            try:
                directory_fd = os.open(directory, os.O_RDONLY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
            except OSError:
                pass
        except Exception:
            try:
                os.unlink(temporary)
            except FileNotFoundError:
                pass
            raise

    def _purge_locked(self):
        now = time.time()
        expired = [key for key, entry in self.entries.items()
                   if entry["expires_at"] is not None and entry["expires_at"] <= now]
        for key in expired:
            del self.entries[key]
        return bool(expired)

    def _load(self):
        if not os.path.exists(self.path):
            return
        try:
            with open(self.path, encoding="utf-8") as file:
                document = json.load(file)
            source = document["entries"]
            if not isinstance(source, dict):
                raise ValueError("entries is not an object")
            now = time.time()
            for key, entry in source.items():
                if (not isinstance(key, str) or not key or "/" in key or
                        not isinstance(entry, dict) or "value" not in entry):
                    raise ValueError("invalid entry")
                expiry = entry.get("expires_at")
                if expiry is not None and (isinstance(expiry, bool) or
                                           not isinstance(expiry, (int, float)) or
                                           not math.isfinite(expiry)):
                    raise ValueError("invalid expiry")
                if valid_json_value(entry["value"]) and (expiry is None or expiry > now):
                    self.entries[key] = {"value": entry["value"], "expires_at": expiry}
            # Rewrite corrupt-looking expired records out of a valid state file.
            self._write_locked()
        except Exception as error:
            print(f"Unable to load data file {self.path}: {error}", file=sys.stderr, flush=True)
            raise RuntimeError("data file is invalid or unreadable") from error

    def get(self, key):
        with self.lock:
            changed = self._purge_locked()
            if changed:
                self._persist_cleanup_locked()
            entry = self.entries.get(key)
            return None if entry is None else entry["value"]

    def keys(self):
        with self.lock:
            if self._purge_locked():
                self._persist_cleanup_locked()
            return sorted(self.entries)

    def _persist_cleanup_locked(self):
        try:
            self._write_locked()
        except OSError as error:
            print(f"Unable to persist expired-entry cleanup: {error}", file=sys.stderr, flush=True)

    def put(self, key, value, ttl):
        with self.lock:
            self._purge_locked()
            existed = key in self.entries
            old = self.entries.get(key)
            self.entries[key] = {"value": value,
                                 "expires_at": None if ttl is None else time.time() + ttl}
            try:
                self._write_locked()
            except Exception:
                if old is None:
                    self.entries.pop(key, None)
                else:
                    self.entries[key] = old
                raise
            return existed

    def delete(self, key):
        with self.lock:
            self._purge_locked()
            old = self.entries.pop(key, None)
            if old is None:
                return False
            try:
                self._write_locked()
            except Exception:
                self.entries[key] = old
                raise
            return True


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    store = None

    def log_message(self, fmt, *args):
        print("%s - %s" % (self.address_string(), fmt % args), file=sys.stderr, flush=True)

    def _send_json(self, status, value=None):
        payload = b"" if status == 204 else json.dumps(
            value, ensure_ascii=False, separators=(",", ":"), allow_nan=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        if payload:
            self.wfile.write(payload)

    def _error(self, status, message):
        self._send_json(status, {"error": message})

    def _key_for_path(self):
        path = urlsplit(self.path).path
        prefix = "/v1/kv/"
        if not path.startswith(prefix):
            return None
        return decode_key(path[len(prefix):])

    def _read_put(self):
        header = self.headers.get("Content-Length")
        if header is None:
            raise RequestError(400, "Content-Length is required")
        try:
            length = int(header)
        except ValueError:
            raise RequestError(400, "invalid Content-Length")
        if length < 0:
            raise RequestError(400, "invalid Content-Length")
        if length > MAX_BODY:
            raise RequestError(413, "request body exceeds 1 MiB")
        raw = self.rfile.read(length)
        if len(raw) != length:
            raise RequestError(400, "incomplete request body")
        try:
            value = json.loads(raw.decode("utf-8"), parse_constant=lambda _: (_ for _ in ()).throw(ValueError()))
        except (UnicodeDecodeError, ValueError, json.JSONDecodeError):
            raise RequestError(400, "malformed JSON")
        if not isinstance(value, dict) or "value" not in value or set(value) - {"value", "ttl_seconds"}:
            raise RequestError(400, "body must contain value and optional ttl_seconds")
        if not valid_json_value(value["value"]):
            raise RequestError(400, "JSON values must be finite")
        ttl = value.get("ttl_seconds")
        if ttl is not None and (isinstance(ttl, bool) or not isinstance(ttl, (int, float)) or
                                not math.isfinite(ttl) or ttl <= 0):
            raise RequestError(400, "ttl_seconds must be a finite number greater than zero")
        return value["value"], ttl

    def _dispatch(self):
        try:
            path = urlsplit(self.path).path
            if self.command == "GET" and path == "/health":
                return self._send_json(200, {"status": "ok"})
            if self.command == "GET" and path == "/v1/keys":
                return self._send_json(200, {"keys": self.store.keys()})
            key = self._key_for_path()
            if key is None:
                raise RequestError(404, "unknown route")
            if self.command == "GET":
                value = self.store.get(key)
                if value is None:
                    raise RequestError(404, "key not found")
                return self._send_json(200, {"key": key, "value": value})
            if self.command == "DELETE":
                if not self.store.delete(key):
                    raise RequestError(404, "key not found")
                return self._send_json(204)
            if self.command == "PUT":
                value, ttl = self._read_put()
                replace = self.store.put(key, value, ttl)
                return self._send_json(200 if replace else 201, {"key": key, "value": value})
            raise RequestError(405, "method not allowed")
        except RequestError as error:
            self._error(error.status, error.message)
        except (OSError, RuntimeError) as error:
            print(f"Request failed: {error}", file=sys.stderr, flush=True)
            self._error(500, "persistent storage error")

    do_GET = _dispatch
    do_PUT = _dispatch
    do_DELETE = _dispatch
    def do_POST(self): self._dispatch()
    def do_PATCH(self): self._dispatch()
    def do_OPTIONS(self): self._dispatch()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", required=True)
    parser.add_argument("--port", type=int, required=True)
    parser.add_argument("--data", required=True)
    args = parser.parse_args()
    if not 0 <= args.port <= 65535:
        parser.error("--port must be between 0 and 65535")
    try:
        Handler.store = Store(args.data)
        server = ThreadingHTTPServer((args.host, args.port), Handler)
    except (OSError, RuntimeError) as error:
        print(f"Startup failed: {error}", file=sys.stderr, flush=True)
        return 1
    print(f"LISTENING {server.server_address[1]}", flush=True)

    def stop(_signum, _frame):
        # shutdown must run in a thread other than serve_forever's thread.
        threading.Thread(target=server.shutdown, daemon=True).start()

    signal.signal(signal.SIGTERM, stop)
    signal.signal(signal.SIGINT, stop)
    try:
        server.serve_forever()
    finally:
        server.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

